SELECT p.id AS position_id, m.id AS managed_id, m.symbol, m.status, m.quantity, m.average_entry_price_usdt, m.total_cost_usdt, m.entry_signal_id, m.entry_confidence, m.entry_total_score, m.entry_decision, m.stop_loss_usdt, m.take_profit_usdt, m.highest_price_usdt, m.profit_lock_active, m.profit_lock_price_usdt, m.profit_lock_progress_percent, m.profit_lock_activated_at, m.opened_at, m.updated_at FROM paper_position p JOIN wallet_managed_position m ON m.symbol=p.symbol AND m.opened_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.opened_at + INTERVAL 10 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id LIMIT 20